// Embedded base64 binary data to guarantee 100% reliable PDF downloads
// and avoid hosting/SPA router issues where index.html is returned instead of PDF.

export const documentPdfBase64: Record<string, string> = {
  "free-agent-agreement": "",
  "short-loan-agreement": "",
  "credit-application-and-guarantee": "",
};

export function downloadPdfBlob(base64Data: string, filename: string): void {
  const binaryString = window.atob(base64Data);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: "application/pdf" });
  const blobUrl = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = blobUrl;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => window.URL.revokeObjectURL(blobUrl), 2000);
}
